pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        address caller = address(uint160(seed));
        vm.assume(caller != address(0));
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        try c.sudicideAnyone() {
            // If no revert, the call succeeded. The contract must be destroyed.
            uint256 codeSize;
            assembly {
                codeSize := extcodesize(c)
            }
            assertTrue(codeSize == 0);
        } catch {
            // If it reverted, the call failed (likely caller is not owner).
            // No assertion needed here; the property is about successful calls.
        }
    }
}

