pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        vm.prank(owner);
        // The owner is msg.sender of setUp (this contract), so we need to become the owner.
        // The constructor sets __owner = msg.sender of deploy, which is this test contract.
        // So we must prank as THIS contract to pass the onlyOwner modifier.
        // But the fuzzer provides owner address. We can use startPrank to set msg.sender.
        vm.startPrank(address(this));
        c.sudicideAnyone();
        vm.stopPrank();
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        assertTrue(codeSize == 0);
    }
}

