pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seedBalance) public {
        // Admissible domain: any non-zero balance that can be given to the contract.
        seedBalance = bound(seedBalance, 1, type(uint128).max);
        address owner = address(0x1111);
        vm.deal(owner, seedBalance);
        vm.prank(owner);
        // First force-pay to the contract (since only owner can call sudicideAnyone).
        // We use a low-level call to send ETH to the contract, as there is no payable receive/fallback defined.
        // However, selfdestruct can still receive ETH. To give the contract a balance, the contract must be the target of a selfdestruct or a miner reward, etc.
        // Since the contract has no payable functions, we can give it a balance by selfdestructing another contract into it.
        // But simpler: we can deploy a temporary payable contract and selfdestruct it to c.
        // We'll use a helper that selfdestructs to c.
        Donor donor = new Donor();
        vm.deal(address(donor), seedBalance);
        donor.donateTo(address(c));

        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        // try/catch to detect revert
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        // After a successful call (it should succeed for owner), the owner's balance must have increased by the contract's prior balance.
        // Because selfdestruct sends all funds to the caller (reference) or to address(0) (bug).
        // In bug, funds go to address(0) and owner gets nothing.
        assertTrue(!ok || owner.balance == ownerBalanceBefore + balanceBefore);
    }
}

contract Donor {
    function donateTo(address payable target) external {
        selfdestruct(target);
    }
}

