pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this);
    }

    function testFuzz_property(address caller) public {
        // Only restrict zero address and the owner (already tested implicitly)
        vm.assume(caller != address(0));
        vm.assume(caller != owner);

        // Give some ETH to the caller just in case
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.sudicideAnyone();

        // After a non-owner calls sudicideAnyone, the reference contract (owner-only)
        // should still exist (code size > 0). The mutant allows any caller,
        // so the contract may be destroyed.
        uint256 size;
        assembly {
            size := extcodesize(c)
        }
        assertTrue(size > 0);
    }
}

