pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(0));
        // Ensure we are not the owner (setUp deploys, so msg.sender in setUp is the owner)
        // We need any fuzzed address that is definitely NOT the owner.
        // Since the owner is the setUp deployer (this test contract), we just prank as the fuzzed nonOwner.
        vm.prank(nonOwner);
        try c.sudicideAnyone() {
            // If the call succeeds (no revert), it means selfdestruct was executed.
            // In the reference, this should never happen for a non-owner.
            // After selfdestruct, the contract code is gone, so extcodesize(c) can be checked.
        } catch {
            // Reference reverts, mutant does not.
            // We can assert the final state after the try/catch.
        }

        // After the attempt, we check the code size of c.
        // For reference (owner required, nonOwner fails), the contract remains, code size > 0.
        // For mutant (anyone can call), the call succeeds, selfdestruct destroys the code, code size == 0.
        uint256 size;
        assembly {
            size := extcodesize(c)
        }
        // Assert: extcodesize > 0 (reference holds, mutant fails because code is destroyed).
        assertTrue(size > 0);
    }
}

